import json
with open('baseline-packages.json') as f: base = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def pkg_map(projects):
    m = {}
    for p in projects:
        name = p['path'].split('/')[-2]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                m[(name, pkg['id'])] = pkg['resolvedVersion']
    return m

b = pkg_map(base['projects'])
a = pkg_map(after['projects'])
changes = []
unchanged = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, '—')
    av = a.get(k, '—')
    if bv != av:
        changes.append((k[0], k[1], bv, av))
    else:
        unchanged.append((k[0], k[1], bv))

print('=== CHANGES ===')
for proj, pkg, old, new in changes:
    print(f'  {proj}/{pkg}: {old} -> {new}')
print()
print(f'=== UNCHANGED ({len(unchanged)} packages) ===')
for proj, pkg, ver in unchanged:
    print(f'  {proj}/{pkg}: {ver}')
"

